import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import restaurantService from '../../services/restaurantService';
import menuItemService from '../../services/menuItemService';
import { useAuth } from '../../hooks/useAuth';
import MenuItemList from './MenuItemList';

const RestaurantDashboard = () => {
  const [restaurant, setRestaurant] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const { token } = useAuth();
  const navigate = useNavigate();

  useEffect(() => {
    const fetchRestaurantDetails = async () => {
      setLoading(true);
      setError('');
      try {
        const restaurantData = await restaurantService.getRestaurantByOwner(token);
        setRestaurant(restaurantData);
      } catch (err) {
        setError(err.message || 'Failed to fetch restaurant details.');
      } finally {
        setLoading(false);
      }
    };

    fetchRestaurantDetails();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [token]);

  if (loading) {
    return <div>Loading dashboard...</div>;
  }

  if (error) {
    return <div style={{ color: 'red' }}>{error}</div>;
  }

  if (!restaurant) {
    return (
      <div>
        <h2>Welcome Restaurant Owner</h2>
        <p>You haven't created a restaurant yet.</p>
        <Link to="/restaurant/add">Add Your Restaurant</Link>
      </div>
    );
  }

  return (
    <div>
      <h2>Restaurant Dashboard</h2>
      <h3>{restaurant.name}</h3>
      <p>Address: {restaurant.address}</p>
      {restaurant.contactNumber && <p>Contact: {restaurant.contactNumber}</p>}
      <Link to={`/restaurant/edit/${restaurant._id}`}>Edit Restaurant Details</Link>

      <h3>Manage Menu Items</h3>
      <Link to="/restaurant/menu/add">Add New Menu Item</Link>
      <MenuItemList restaurantId={restaurant._id} />
    </div>
  );
};

export default RestaurantDashboard;
